static void test_sc_add()
{
    std::cout << std::endl << "=== sc_add ===" << std::endl;
    unsigned char out[32];
    sc_add(out, test_vectors::scalar_a, test_vectors::scalar_b);
    check_bytes("sc_add(a, b)", test_vectors::sc_add_ab, out, 32);
}

