static void test_ge_frombytes_reject_noncanonical()
{
    std::cout << std::endl << "=== ge_frombytes reject non-canonical y ===" << std::endl;

    // y = p = 2^255 - 19 (non-canonical encoding of y = 0)
    const unsigned char noncanon_y_p[] = {0xed, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};

    // y = p + 1 = 2^255 - 18
    const unsigned char noncanon_y_p1[] = {0xee, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                           0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                           0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};

    // y = 2^255 - 1 (maximum 255-bit value, well above p)
    const unsigned char noncanon_y_max[] = {0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};

    auto test_reject = [](const char *name, const unsigned char *input)
    {
        ge_p3 p3;
        int rc = ge_frombytes_vartime(&p3, input);
        check_int(name, -1, rc);
    };

    test_reject("reject y = p (non-canonical)", noncanon_y_p);
    test_reject("reject y = p+1 (non-canonical)", noncanon_y_p1);
    test_reject("reject y = 2^255-1 (non-canonical)", noncanon_y_max);

    // Also test with sign bit set (high bit of last byte)
    unsigned char noncanon_signed[32];

    std::memcpy(noncanon_signed, noncanon_y_p, 32);
    noncanon_signed[31] |= 0x80;
    test_reject("reject y = p with sign bit", noncanon_signed);

    std::memcpy(noncanon_signed, noncanon_y_p1, 32);
    noncanon_signed[31] |= 0x80;
    test_reject("reject y = p+1 with sign bit", noncanon_signed);

    // Boundary: y = p - 1 = 2^255 - 20 IS canonical (should succeed)
    const unsigned char canon_y_pm1[] = {0xec, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};
    {
        ge_p3 p3;
        int rc = ge_frombytes_vartime(&p3, canon_y_pm1);
        check_int("accept y = p-1 (canonical, on curve)", 0, rc);
    }
}

