static void test_ristretto255_encode_decode()
{
    std::cout << std::endl << "=== ristretto255 encode/decode ===" << std::endl;

    // Compute [0]B through [15]B via repeated addition from the base point
    ge_p3 points[16];

    // [0]B = identity
    ge_p3_0(&points[0]);

    // [1]B = base point via scalarmult_base_ct
    {
        const unsigned char scalar_one[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        ge_p1p1 r;
        ge_scalarmult_base_ct(&r, scalar_one);
        ge_p1p1_to_p3(&points[1], &r);
    }

    // [i]B = [i-1]B + [1]B for i = 2..15
    ge_cached base_cached;
    ge_p3_to_cached(&base_cached, &points[1]);
    for (int i = 2; i <= 15; ++i)
    {
        ge_p1p1 sum;
        ge_add(&sum, &points[i - 1], &base_cached);
        ge_p1p1_to_p3(&points[i], &sum);
    }

    // Encode each and compare to expected
    for (int i = 0; i <= 15; ++i)
    {
        unsigned char encoded[32];
        ristretto255_encode(encoded, &points[i]);

        std::string name = "encode [" + std::to_string(i) + "]B";
        check_bytes(name.c_str(), test_vectors::ristretto_generator_multiples[i], encoded, 32);
    }

    // Decode each expected encoding and re-encode (roundtrip)
    for (int i = 0; i <= 15; ++i)
    {
        ge_p3 decoded;
        unsigned char reencoded[32];

        int rc = ristretto255_decode(&decoded, test_vectors::ristretto_generator_multiples[i]);
        std::string name_rc = "decode [" + std::to_string(i) + "]B rc";

        if (i == 0)
        {
            // Identity: the all-zero encoding
            check_int(name_rc.c_str(), 0, rc);
            ristretto255_encode(reencoded, &decoded);
            std::string name = "roundtrip [0]B";
            check_bytes(name.c_str(), test_vectors::ristretto_generator_multiples[0], reencoded, 32);
        }
        else
        {
            check_int(name_rc.c_str(), 0, rc);
            ristretto255_encode(reencoded, &decoded);
            std::string name = "roundtrip [" + std::to_string(i) + "]B";
            check_bytes(name.c_str(), test_vectors::ristretto_generator_multiples[i], reencoded, 32);
        }
    }

    // Test ristretto255_equals on decoded points
    {
        ge_p3 p1_from_encode;
        ristretto255_decode(&p1_from_encode, test_vectors::ristretto_generator_multiples[1]);
        // points[1] is the same point from scalarmult
        int eq = ristretto255_equals(&p1_from_encode, &points[1]);
        check_int("equals: decoded [1]B == scalarmult [1]B", 1, eq);

        // Different points should not be equal
        int neq = ristretto255_equals(&points[1], &points[2]);
        check_int("equals: [1]B != [2]B", 0, neq);
    }
}

