    test_sc_mulsub();
    test_sc_reduce();
    test_sc_clamp();
    test_sc_check_reduced();
    test_sc_check_clamped();
    test_sc_isnonzero();

    // Field element operations
    test_fe_roundtrip();
    test_fe_arithmetic();

    // Group element operations
    test_ge_scalarmult_base_ct();

    test_ge_frombytes();
    test_ge_fromfe_frombytes();
    test_ge_check_subgroup_precomp_vartime();
    test_ge_check_subgroup_precomp_negate_vartime();

    // Input validation
    test_ge_frombytes_reject_noncanonical();
    test_ge_frombytes_reject_offcurve();
    test_ge_subgroup_order8_points();

    // Ristretto255
    test_ristretto255_encode_decode();
    test_ristretto255_bad_encodings();
    test_ristretto255_from_uniform_bytes();

    // Wei25519
    test_ge_p3_to_wei25519();

    // Batch operations
    test_ge_scalarmult_ct_batch();
    test_ge_dsm_base_negate_vartime_batch();
    test_ge_dsm_negate_vartime_batch();
    test_ge_dsm_negate_vartime_batch_ss();
    test_ge_dsm_negate_vartime_batch_ss_p3();

    // Multi-scalar multiplication
    test_ge_multiscalar_mul_vartime();
    test_ge_multiscalar_mul_base_vartime();

    // Edge-case tests
    test_scalarmult_zero_scalar();
    test_scalarmult_identity_point();
